use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use serde::Serialize;
use std::collections::HashMap;
use std::io::{self, BufWriter, Write};

const QUARTER_HOUR_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLING_SECONDS: i64 = 30 * 60;

#[derive(Debug, Serialize, PartialEq, Eq)]
struct InvoiceProject {
    project: String,
    billable_seconds: i64,
}

#[derive(Debug, Serialize, PartialEq, Eq)]
struct Invoice {
    projects: Vec<InvoiceProject>,
    total_billable_seconds: i64,
}

pub struct InvoiceCommand;

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let invoice = build_invoice(&entries);

        if json {
            let stdout = io::stdout();
            let mut handle = BufWriter::new(stdout);
            writeln!(
                handle,
                "{}",
                serde_json::to_string(&invoice).expect("failed to serialize invoice")
            )
            .expect("failed to print invoice");
        } else if invoice.projects.is_empty() {
            println!("(no data)");
        } else {
            let stdout = io::stdout();
            let mut handle = BufWriter::new(stdout);
            for item in &invoice.projects {
                writeln!(handle, "{}s  {}", item.billable_seconds, item.project)
                    .expect("failed to print invoice");
            }
            writeln!(handle, "{}s  Total", invoice.total_billable_seconds)
                .expect("failed to print invoice");
        }

        Ok(())
    }
}

fn build_invoice(entries: &[TimeEntry]) -> Invoice {
    let mut totals: HashMap<String, i64> = HashMap::new();

    for entry in entries {
        if !entry.billable || entry.stop.is_none() {
            continue;
        }

        let duration = entry.duration.max(0);
        let rounded =
            ((duration + QUARTER_HOUR_SECONDS - 1) / QUARTER_HOUR_SECONDS) * QUARTER_HOUR_SECONDS;
        let charged = rounded.max(MINIMUM_BILLING_SECONDS);
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *totals.entry(project).or_default() += charged;
    }

    let mut projects: Vec<_> = totals
        .into_iter()
        .map(|(project, billable_seconds)| InvoiceProject {
            project,
            billable_seconds,
        })
        .collect();
    projects.sort_by(|left, right| {
        right
            .billable_seconds
            .cmp(&left.billable_seconds)
            .then_with(|| left.project.cmp(&right.project))
    });
    let total_billable_seconds = projects.iter().map(|item| item.billable_seconds).sum();

    Invoice {
        projects,
        total_billable_seconds,
    }
}

