                total_billable_seconds: 8_100,
            }
        );
    }

    #[test]
    fn zero_duration_stopped_entry_gets_minimum() {
        assert_eq!(
            build_invoice(&[entry(1, 0, true, true, None)]).total_billable_seconds,
            1_800
        );
    }
}
